const app = document.querySelector<HTMLDivElement>('#app') as HTMLDivElement;
if (!app) throw new Error('缺少应用挂载节点');

let snapshot: PublicSnapshot;
let portfolio: LocalPortfolio = emptyPortfolio();
let advice: AdviceResult;

const REGIME = {
  GREEN: { zh: '绿色', copy: '风险预算充足', tone: '#79d6a0' },
  YELLOW: { zh: '黄色', copy: '保持均衡', tone: '#e8cd68' },
  ORANGE: { zh: '橙色', copy: '风险正在收缩', tone: '#ee9b62' },
  RED: { zh: '红色', copy: '优先控制风险', tone: '#ef7076' },
  'DATA ERROR': { zh: '数据错误', copy: '暂停新的建议', tone: '#d989ef' },
} as const;

function narrative(): string {
  if (snapshot.health.blocking) return '数据质量门槛未通过。系统保留上一份已确认方案，不生成新的人工再平衡建议。';
  const risk = snapshot.risk;
  const trend = risk.trendBreadth >= .67 ? '权益趋势整体有支撑' : risk.trendBreadth >= .33 ? '权益趋势出现分化' : '多数权益趋势偏弱';
  const volatility = risk.volScore >= .9 ? '波动压力较低' : risk.volScore >= .65 ? '波动开始约束风险预算' : '波动压力显著';
  return `${trend}，${volatility}。模型把已确认权益目标控制在${percent(risk.confirmedEquityTarget)}，这是风险预算，不是涨跌预测。`;
}

function factor(title: string, weight: string, value: number, meaning: string, implication: string): string {
  return `<article class="factor reveal"><span class="factor-index">${weight}</span><div><div class="factor-title"><h3>${title}</h3><strong>${percent(value)}</strong></div><div class="track"><i style="width:${Math.max(0, Math.min(100, value * 100))}%"></i></div></div><p>${meaning}<strong>${implication}</strong></p></article>`;
}

function sparkline(points: Array<{ value: number }>, width = 720, height = 190): string {
  if (!points.length) return '';
  const values = points.map((point) => point.value);
  const min = Math.min(...values);
  const max = Math.max(...values);
  const span = Math.max(max - min, .0001);
  const path = points.map((point, index) => {
    const x = index / Math.max(1, points.length - 1) * width;
    const y = height - ((point.value - min) / span * (height - 16) + 8);
    return `${index ? 'L' : 'M'}${x.toFixed(1)},${y.toFixed(1)}`;
  }).join(' ');
  return `<svg class="sparkline" viewBox="0 0 ${width} ${height}" role="img" aria-label="历史曲线"><path d="${path}" /></svg>`;
}

function assetRow(asset: PublicAsset): string {
  const current = advice.available ? advice.currentWeights[asset.code] : null;
  const gap = current == null ? null : asset.confirmedTarget - current;
  return `<tr data-code="${asset.code}" tabindex="0">
    <td><strong>${escapeHtml(asset.name)}</strong><span>${asset.code} · ${escapeHtml(asset.role)}</span></td>
    <td>${percent(asset.return63)}</td><td>${percent(asset.return126)}</td><td>${percent(asset.return252)}</td>
    <td>${percent(asset.forecastVol)}</td><td>${asset.relativeStrength == null ? '—' : number(asset.relativeStrength, 2)}</td>
    <td>${percent(current)}</td><td><strong>${percent(asset.confirmedTarget)}</strong></td>
    <td class="${gap != null && gap > 0 ? 'positive' : gap != null && gap < 0 ? 'negative' : ''}">${percent(gap)}</td>
  </tr>`;
}

function adviceMarkup(): string {
  if (snapshot.health.blocking) return '<div class="decision-note blocked"><strong>暂停建议</strong><p>数据健康检查未通过。请等待数据流水线恢复，勿依据本次页面新增交易。</p></div>';
  if (!advice.available) return '<div class="decision-note"><strong>先录入本机持仓</strong><p>页面已经显示模型目标；只有录入当前市值后，才会计算免交易区间、50%部分再平衡和建议金额。</p><button class="text-button" data-open-portfolio>录入持仓 →</button></div>';
  const active = advice.rows.filter((row) => row.action !== 'NO TRADE');
  if (!active.length) return '<div class="decision-note calm"><strong>NO TRADE · 无需操作</strong><p>所有资产均在免交易区间内，减少调仓比追逐细小偏差更重要。</p></div>';
  return `<div class="advice-list">${advice.rows.map((row) => `<article class="advice-row ${row.action === 'NO TRADE' ? 'muted' : ''}">
    <div><span>${row.code}</span><strong>${row.action === 'BUY' ? '建议增加' : row.action === 'SELL' ? '建议降低' : '无需操作'}</strong></div>
    <b class="${row.tradeWeight > 0 ? 'positive' : row.tradeWeight < 0 ? 'negative' : ''}">${money(row.suggestedAmount)}</b>
    <p>当前 ${percent(row.currentWeight)} → 目标 ${percent(row.targetWeight)}；免交易带 ${percent(row.band)}。${escapeHtml(row.reason)}</p>
  </article>`).join('')}</div>`;
}

function backtestMarkup(): string {
  if (snapshot.backtest.status !== 'OK') return '<p class="empty">回测尚未生成。</p>';
  const rows = snapshot.backtest.strategies.map((strategy) => `<tr class="${strategy.key === 'D_FRAIS_V1' ? 'selected' : ''}">
    <td><strong>${escapeHtml(strategy.label)}</strong></td><td>${percent(strategy.metrics.cagr)}</td>
    <td>${percent(strategy.metrics.annualVolatility)}</td><td>${percent(strategy.metrics.maxDrawdown)}</td>
    <td>${number(strategy.metrics.sharpe)}</td><td>${percent(strategy.metrics.turnover)}</td>
    <td>${number(strategy.metrics.tradeCount, 0)}</td><td>${number(strategy.metrics.recoveryDays, 0)}</td>
  </tr>`).join('');
  const frais = snapshot.backtest.strategies.find((strategy) => strategy.key === 'D_FRAIS_V1');
  return `<div class="backtest-summary"><div><span>回测区间</span><strong>${snapshot.backtest.period.start} → ${snapshot.backtest.period.end}</strong></div>
    <div><span>交易成本</span><strong>${percent(snapshot.backtest.costRate, 2)}</strong></div>
    <div><span>参数网格</span><strong>${snapshot.backtest.robustness.cases} 组</strong></div>
    <div><span>稳健性</span><strong class="${snapshot.backtest.robustness.warning ? 'warning' : 'positive'}">${snapshot.backtest.robustness.warning ? '过拟合警告' : '通过'}</strong></div></div>
    <div class="nav-plot">${frais ? sparkline(frais.nav) : ''}<span>FRAIS V1 历史净值，仅供比较</span></div>
    <div class="table-scroll"><table class="metrics-table"><thead><tr><th>策略</th><th>CAGR</th><th>年化波动</th><th>最大回撤</th><th>Sharpe</th><th>年换手</th><th>交易次数</th><th>恢复天数</th></tr></thead><tbody>${rows}</tbody></table></div>
    <p class="method-note">解读：系统不按历史收益最高选择参数。稳健性门槛只检验不同参数区域的回撤控制是否具有广泛支持；完整敏感性结果可<a href="./data/parameter-sensitivity.csv" download>下载 CSV</a>。</p>`;
}

