import type { AdviceRow, AssetCode, LocalPortfolio, PublicAsset } from './types';
import { ASSET_CODES } from './types';

export interface AdviceResult {
  available: boolean;
  totalValue: number;
  currentWeights: Record<AssetCode, number>;
  currentEquity: number;
  cashWeight: number;
  premiumStatus: string;
  rows: AdviceRow[];
}

export function emptyPortfolio(): LocalPortfolio {
  return {
    schemaVersion: 1,
    updatedAt: new Date(0).toISOString(),
    values: { '512890': 0, '513100': 0, '588000': 0, '518880': 0, '511010': 0 },
    cash: 0,
    qdiiPremium: null,
  };
}

function premiumStatus(premium: number | null): string {
  if (premium == null || !Number.isFinite(premium)) return '需要人工输入';
  if (premium >= 0.05) return 'RED WARNING';
  if (premium >= 0.03) return '禁止新增买入';
  if (premium >= 0.015) return '仅执行50%买入';
  return '正常';
}

export function calculateAdvice(portfolio: LocalPortfolio, assets: PublicAsset[]): AdviceResult {
  const invested = ASSET_CODES.reduce((total, code) => total + Math.max(0, portfolio.values[code] || 0), 0);
  const cash = Math.max(0, portfolio.cash || 0);
  const totalValue = invested + cash;
  const currentWeights = Object.fromEntries(ASSET_CODES.map((code) => [
    code, totalValue > 0 ? Math.max(0, portfolio.values[code] || 0) / totalValue : 0,
  ])) as Record<AssetCode, number>;
  const target = Object.fromEntries(assets.map((asset) => [asset.code, asset.confirmedTarget])) as Record<AssetCode, number>;
  const gaps = Object.fromEntries(ASSET_CODES.map((code) => [code, (target[code] ?? 0) - currentWeights[code]])) as Record<AssetCode, number>;
  const bands = Object.fromEntries(ASSET_CODES.map((code) => [code, Math.max(0.01, 0.15 * (target[code] ?? 0))])) as Record<AssetCode, number>;
  const deltas = Object.fromEntries(ASSET_CODES.map((code) => [
    code, Math.abs(gaps[code]) >= bands[code] ? 0.5 * gaps[code] : 0,
  ])) as Record<AssetCode, number>;

  const buys = ASSET_CODES.reduce((sum, code) => sum + Math.max(0, deltas[code]), 0);
  const sells = ASSET_CODES.reduce((sum, code) => sum + Math.max(0, -deltas[code]), 0);
  const buyBudget = sells + (totalValue > 0 ? cash / totalValue : 0);
  if (buys > buyBudget && buys > 0) {
    const factor = buyBudget / buys;
    ASSET_CODES.forEach((code) => { if (deltas[code] > 0) deltas[code] *= factor; });
  } else if (sells > buys && sells > 0) {
    const factor = buys / sells;
    ASSET_CODES.forEach((code) => { if (deltas[code] < 0) deltas[code] *= factor; });
  }

  const originalQdiiBuy = Math.max(0, deltas['513100']);
  let qdiiFactor = 1;
  if (portfolio.qdiiPremium == null || portfolio.qdiiPremium >= 0.03) qdiiFactor = 0;
  else if (portfolio.qdiiPremium >= 0.015) qdiiFactor = 0.5;
  if (originalQdiiBuy > 0) {
    deltas['513100'] = originalQdiiBuy * qdiiFactor;
    deltas['511010'] += originalQdiiBuy - deltas['513100'];
  }

  const rows = ASSET_CODES.map((code): AdviceRow => {
    const tradeWeight = deltas[code];
    let action: AdviceRow['action'] = 'NO TRADE';
    let reason = Math.abs(gaps[code]) < bands[code] ? '处于免交易区间内' : '受自融资约束，当前不产生可执行建议';
    if (tradeWeight > 1e-10) { action = 'BUY'; reason = '按目标缺口的50%进行部分再平衡'; }
    if (tradeWeight < -1e-10) { action = 'SELL'; reason = '按目标缺口的50%进行部分再平衡'; }
    if (code === '513100' && originalQdiiBuy > deltas[code]) reason = 'QDII溢价门控限制新增买入，不影响风险模型';
    if (code === '511010' && originalQdiiBuy - deltas['513100'] > 0) reason = '暂时承接被QDII溢价门控拦截的计划资金';
    return {
      code, currentWeight: currentWeights[code], targetWeight: target[code] ?? 0,
      gap: gaps[code], band: bands[code], tradeWeight,
      suggestedAmount: tradeWeight * totalValue, action, reason,
    };
  });
  return {
    available: totalValue > 0,
    totalValue,
    currentWeights,
    currentEquity: currentWeights['512890'] + currentWeights['513100'] + currentWeights['588000'],
    cashWeight: totalValue > 0 ? cash / totalValue : 0,
    premiumStatus: premiumStatus(portfolio.qdiiPremium),
    rows,
  };
}
